export type ArtifactKind = 'original' | 'mask' | 'overlay';
export const ARTIFACT_KINDS: readonly ArtifactKind[] = ['original', 'mask', 'overlay'];
export type ArtifactExtension = 'png' | 'jpg' | 'webp';

export const ARTIFACT_STORAGE = 'ArtifactStorage';

/**
 * Private storage for MRI images. Implementations must never be reachable without the
 * caller having performed an authorization check. Keys are generated by the server.
 */
export interface ArtifactStorage {
  put(key: string, data: Buffer): Promise<void>;
  /** Returns null when the object does not exist. */
  get(key: string): Promise<Buffer | null>;
  deleteCase(caseId: string): Promise<void>;
}

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const KEY_PATTERN = new RegExp(`^(${UUID})/(${UUID})/(original|mask|overlay)\\.(png|jpg|webp)$`);
// Keys written by earlier versions: "org/default/case/<case>/mri/<mri>/<kind>.png"
const LEGACY_KEY_PATTERN = new RegExp(`^org/default/case/(${UUID})/mri/(${UUID})/(original|mask|overlay)\\.png$`);

export function buildArtifactKey(caseId: string, mriId: string, kind: ArtifactKind, ext: ArtifactExtension): string {
  const key = `${caseId}/${mriId}/${kind}.${ext}`;
  if (!KEY_PATTERN.test(key)) {
    throw new Error('Invalid artifact key components');
  }
  return key;
}

/** Validates a stored key and returns its canonical relative path, or null if malformed. */
export function parseArtifactKey(key: string): { caseId: string; mriId: string; relativePath: string; ext: string } | null {
  const current = KEY_PATTERN.exec(key);
  if (current) {
    return { caseId: current[1], mriId: current[2], relativePath: key, ext: current[4] };
  }
  const legacy = LEGACY_KEY_PATTERN.exec(key);
  if (legacy) {
    return { caseId: legacy[1], mriId: legacy[2], relativePath: `${legacy[1]}/${legacy[2]}/${legacy[3]}.png`, ext: 'png' };
  }
  return null;
}

export function contentTypeForKey(key: string): string {
  switch (parseArtifactKey(key)?.ext) {
    case 'jpg':
      return 'image/jpeg';
    case 'webp':
      return 'image/webp';
    default:
      return 'image/png';
  }
}
